-- Opens the release as DuckDB views with documented columns. Run from the repository root:
--   duckdb -init data/release/open.sql   or   con.execute(open('data/release/open.sql').read())
-- List every table and column with its meaning:
--   SELECT table_name, column_name, comment FROM duckdb_columns() WHERE comment IS NOT NULL;

CREATE OR REPLACE VIEW about AS SELECT * FROM read_parquet('data/release/parquet/about.parquet');
COMMENT ON VIEW about IS 'Build information: date, sources, years, audit summary. | מידע על הבנייה: תאריך, מקורות, שנים, סיכום הבדיקות. | grain: key';
COMMENT ON COLUMN about."key" IS 'item | שם הפריט';
COMMENT ON COLUMN about."value" IS 'value | ערך';

CREATE OR REPLACE VIEW topics AS SELECT * FROM read_parquet('data/release/parquet/topics.parquet');
COMMENT ON VIEW topics IS 'Stable topics grouping the indicators, with the number of indicators in each. | נושאים קבועים לקיבוץ מדדים, עם מספר המדדים בכל נושא. | grain: topic';
COMMENT ON COLUMN topics."topic" IS 'topic key | מפתח הנושא (אנגלית)';
COMMENT ON COLUMN topics."topic_name" IS 'topic name (Hebrew) | שם הנושא';
COMMENT ON COLUMN topics."n_indicators" IS 'number of indicators | מספר מדדים בנושא';

CREATE OR REPLACE VIEW indicators AS SELECT * FROM read_parquet('data/release/parquet/indicators.parquet');
COMMENT ON VIEW indicators IS 'Indicator catalogue: what exists, for which years, at what quality and how indicators relate. Start every query here. | קטלוג המדדים: מה קיים, לאילו שנים, באיזו איכות ומה קשור למה. נקודת הפתיחה לכל שאילתה. | grain: indicator';
COMMENT ON COLUMN indicators."indicator_id" IS 'stable id. P = physical/population sheets, B = budget sheets. Suffix _k = derived per 1,000 residents | מזהה יציב. P = נתונים פיזיים ואוכלוסייה, B = תקציב. סיומת _k = נגזר ל-1,000 תושבים';
COMMENT ON COLUMN indicators."name" IS 'indicator name without years or footnote marks; levels joined by › | שם המדד בלי שנים והערות שוליים, רמות מופרדות ב-›';
COMMENT ON COLUMN indicators."full_label" IS 'full header as printed in the latest file | הכותרת המלאה כפי שהופיעה בקובץ האחרון';
COMMENT ON COLUMN indicators."topic" IS 'topic (see topics) | נושא (ראו טבלת topics)';
COMMENT ON COLUMN indicators."topic_name" IS 'topic name | שם הנושא';
COMMENT ON COLUMN indicators."domain" IS 'source sheet family | גיליון מקור: physical / budget / landuse / derived';
COMMENT ON COLUMN indicators."measure_type" IS 'count | rate | index | attribute | count = כמות מוחלטת (גדלה עם גודל הרשות) · rate = שיעור/אחוז/ממוצע · index = מדד מורכב/אשכול/דירוג · attribute = תכונה/מזהה';
COMMENT ON COLUMN indicators."measure_type_basis" IS 'basis of measure_type: label, or a data check that corrected it | על מה מבוסס הסיווג: label, או בדיקת נתונים שתיקנה אותו';
COMMENT ON COLUMN indicators."value_type" IS 'numeric or text | numeric או text (למשל מחוז, רמת פריפריאליות בקטגוריות)';
COMMENT ON COLUMN indicators."unit" IS 'unit after unit decisions; empty = not stated in the header | יחידה (אחרי המרת יחידות). ריק = לא צוינה בכותרת';
COMMENT ON COLUMN indicators."unit_note" IS 'unit conversions applied, by file year | המרות יחידה שהוחלו, לפי שנות קובץ';
COMMENT ON COLUMN indicators."period_kind" IS 'what `year` means for this indicator | calendar_year · school_year (שנת לימודים, השנה = שנת הסיום) · multi_year (ממוצע רב-שנתי, השנה = שנת הסיום) · reference_year (מהדורת מדד / שנת ייחוס)';
COMMENT ON COLUMN indicators."first_year" IS 'first data year with a value | שנת הנתון הראשונה עם ערך';
COMMENT ON COLUMN indicators."last_year" IS 'last data year with a value | שנת הנתון האחרונה עם ערך';
COMMENT ON COLUMN indicators."n_years" IS 'number of data years with a value | מספר שנות נתון עם ערך';
COMMENT ON COLUMN indicators."years" IS 'all data years with a value | כל שנות הנתון עם ערך, מופרדות בפסיקים';
COMMENT ON COLUMN indicators."missing_years" IS 'years inside the range without a value | שנים בתוך הטווח שאין בהן ערך';
COMMENT ON COLUMN indicators."n_authorities_last_year" IS 'authorities with a value in the last year | מספר רשויות עם ערך בשנה האחרונה';
COMMENT ON COLUMN indicators."applies_to" IS 'municipal statuses that have values | מעמדות הרשויות שיש להן ערכים (עירייה / מועצה מקומית / מועצה אזורית)';
COMMENT ON COLUMN indicators."quality_flags" IS 'summary of known quality issues (empty = none) | סיכום בעיות איכות ידועות במדד (ריק = אין)';
COMMENT ON COLUMN indicators."mapping_uncertain_columns" IS 'source columns mapped with medium/low confidence | מספר עמודות מקור שהשיוך שלהן לסדרה ברמת ביטחון medium/low';
COMMENT ON COLUMN indicators."revised_values" IS 'values a later file revised | מספר ערכים שקובץ מאוחר דיווח עליהם ערך שונה';
COMMENT ON COLUMN indicators."consistency_violations" IS 'values violating an internal identity of the CBS data | מספר ערכים שסותרים זהות פנימית בנתוני הלמ"ס (למשל אחוז ≠ מונה/מכנה)';
COMMENT ON COLUMN indicators."mixed_scale_values" IS 'values that look like fractions inside a percentage column (source problem) | מספר ערכים שנראים כשבר בעמודה של אחוזים (בעיה בקובץ המקור)';
COMMENT ON COLUMN indicators."systematic_breaks" IS 'year transitions where many authorities jump >=10x together | מעברי שנים שבהם רבות מהרשויות קופצות פי 10 ומעלה יחד (שינוי יחידה/הגדרה לא מטופל)';
COMMENT ON COLUMN indicators."estimate_share" IS 'share of values that are estimates | שיעור הערכים שהם אומדן (בסוגריים במקור)';
COMMENT ON COLUMN indicators."same_values_as" IS 'indicators with identical values (the same data published twice) | מדדים עם ערכים זהים (אותו נתון שפורסם בשני מקומות)';
COMMENT ON COLUMN indicators."continues" IS 'indicators that may be this series before a wording/structure change (not merged) | מדדים שייתכן שהם אותה סדרה לפני שינוי ניסוח/מבנה (לא אוחדו; לבדיקה)';
COMMENT ON COLUMN indicators."continued_by" IS 'indicators that may continue this series (not merged) | מדדים שייתכן שהם המשך הסדרה (לא אוחדו; לבדיקה)';
COMMENT ON COLUMN indicators."derived_from" IS 'for a derived indicator: its base indicator | למדד נגזר: המדד שממנו חושב';
COMMENT ON COLUMN indicators."label_history" IS 'source headers by file year | הכותרות בקבצי המקור לפי שנות קובץ';
COMMENT ON COLUMN indicators."source_columns" IS 'number of source columns forming the indicator | מספר עמודות מקור שמרכיבות את המדד';

CREATE OR REPLACE VIEW coverage AS SELECT * FROM read_parquet('data/release/parquet/coverage.parquet');
COMMENT ON VIEW coverage IS 'Availability per indicator and year: authorities with a value, nil, not available, estimate. | זמינות: לכל מדד ושנה, כמה רשויות יש להן ערך, "אין מקרים", "לא ידוע", אומדן. | grain: indicator × year';
COMMENT ON COLUMN coverage."indicator_id" IS 'indicator id | מזהה מדד';
COMMENT ON COLUMN coverage."year" IS 'data year | שנת נתון';
COMMENT ON COLUMN coverage."n_authorities" IS 'authorities existing that year | מספר הרשויות הקיימות באותה שנה';
COMMENT ON COLUMN coverage."n_values" IS 'authorities with a value | רשויות עם ערך (מספר או טקסט)';
COMMENT ON COLUMN coverage."n_nil" IS 'authorities marked "-" (no cases) | רשויות שסומנו "-" (אין מקרים)';
COMMENT ON COLUMN coverage."n_not_available" IS 'authorities marked ".." (unknown / not publishable) | רשויות שסומנו ".." (לא ידוע / לא לפרסום)';
COMMENT ON COLUMN coverage."n_estimate" IS 'values that are estimates | ערכים שהם אומדן';
COMMENT ON COLUMN coverage."n_east_galilee" IS 'East Galilee authorities with a value | רשויות הגליל המזרחי עם ערך';
COMMENT ON COLUMN coverage."n_west_galilee" IS 'West Galilee authorities with a value | רשויות הגליל המערבי עם ערך';
COMMENT ON COLUMN coverage."share_with_value" IS 'n_values / n_authorities | n_values / n_authorities';

CREATE OR REPLACE VIEW authorities AS SELECT * FROM read_parquet('data/release/parquet/authorities.parquet');
COMMENT ON VIEW authorities IS 'Local authorities (any that appeared in any year), with Eshkol membership. | הרשויות המקומיות (כל מי שהופיעה בשנה כלשהי), עם שיוך לאשכול. | grain: authority';
COMMENT ON COLUMN authorities."muni_code" IS 'CBS authority code (2024 scheme: regional council = 5500 + number) | סמל הרשות בלמ"ס (סכמת 2024: מועצה אזורית = 5500 + מספר)';
COMMENT ON COLUMN authorities."name" IS 'name in the latest file it appears in | השם בקובץ האחרון שבו הופיעה';
COMMENT ON COLUMN authorities."status" IS 'latest municipal status | מעמד מוניציפלי אחרון';
COMMENT ON COLUMN authorities."district" IS 'latest district | מחוז אחרון';
COMMENT ON COLUMN authorities."first_year" IS 'first year present | השנה הראשונה שבה הופיעה';
COMMENT ON COLUMN authorities."last_year" IS 'last year present | השנה האחרונה שבה הופיעה';
COMMENT ON COLUMN authorities."n_years" IS 'years present | מספר שנים שבהן הופיעה';
COMMENT ON COLUMN authorities."eshkol" IS 'Eshkol cluster or empty | אשכול: גליל מזרחי / גליל מערבי / ריק';
COMMENT ON COLUMN authorities."eshkol_name" IS 'name in the Eshkol list | השם ברשימת האשכול';
COMMENT ON COLUMN authorities."sector" IS 'sector (Eshkol authorities) | מגזר (לרשויות האשכול)';
COMMENT ON COLUMN authorities."settlement_form" IS 'settlement form (Eshkol authorities) | צורת יישוב (לרשויות האשכול)';
COMMENT ON COLUMN authorities."aliases" IS 'all known spellings, |-separated | כל הכתיבים המוכרים, מופרדים ב-|';

CREATE OR REPLACE VIEW authority_aliases AS SELECT * FROM read_parquet('data/release/parquet/authority_aliases.parquet');
COMMENT ON VIEW authority_aliases IS 'Every spelling of an authority name → code. Search on alias_normalized. | כל כתיב של שם רשות (למ"ס לאורך השנים, רשימת האשכול) → סמל. לחיפוש לפי שם השתמשו ב-alias_normalized. | grain: alias × authority';
COMMENT ON COLUMN authority_aliases."alias" IS 'spelling as it appeared | הכתיב כפי שהופיע';
COMMENT ON COLUMN authority_aliases."alias_normalized" IS 'normalized: no quotes, hyphens, brackets | הכתיב אחרי ניקוי (בלי גרשיים, מקפים, סוגריים)';
COMMENT ON COLUMN authority_aliases."muni_code" IS 'authority code | סמל הרשות';
COMMENT ON COLUMN authority_aliases."source" IS 'where the spelling comes from | מקור הכתיב';

CREATE OR REPLACE VIEW authority_year AS SELECT * FROM read_parquet('data/release/parquet/authority_year.parquet');
COMMENT ON VIEW authority_year IS 'Authority attributes by year: status, population, socio-economic and peripherality clusters. | מאפייני רשות לפי שנה: מעמד, אוכלוסייה, אשכול חברתי-כלכלי ופריפריאליות. | grain: authority × year';
COMMENT ON COLUMN authority_year."muni_code" IS 'authority code | סמל הרשות';
COMMENT ON COLUMN authority_year."year" IS 'year (file year) | שנה (שנת הקובץ)';
COMMENT ON COLUMN authority_year."name" IS 'name that year | השם באותה שנה';
COMMENT ON COLUMN authority_year."status" IS 'municipal status that year | מעמד מוניציפלי באותה שנה';
COMMENT ON COLUMN authority_year."district" IS 'district that year | מחוז באותה שנה';
COMMENT ON COLUMN authority_year."population" IS 'population at year end (persons) | אוכלוסייה בסוף השנה (נפשות)';
COMMENT ON COLUMN authority_year."ses_cluster" IS 'SES cluster 1-10, latest edition published by that year | אשכול חברתי-כלכלי 1–10 לפי המהדורה האחרונה שפורסמה עד אותה שנה';
COMMENT ON COLUMN authority_year."ses_value" IS 'SES index value, same edition | ערך המדד החברתי-כלכלי באותה מהדורה';
COMMENT ON COLUMN authority_year."ses_edition" IS 'SES edition used | שנת מהדורת המדד החברתי-כלכלי שבה השתמשנו';
COMMENT ON COLUMN authority_year."ses_cluster_latest" IS 'SES cluster in the latest edition (fixed peer group) | אשכול חברתי-כלכלי במהדורה האחרונה (קבוצת השוואה קבועה לאורך השנים)';
COMMENT ON COLUMN authority_year."ses_edition_latest" IS 'latest SES edition | שנת המהדורה האחרונה';
COMMENT ON COLUMN authority_year."periphery_cluster" IS 'peripherality cluster 1-10 (1 = most peripheral) | אשכול פריפריאליות 1–10 (1 = הפריפריאלי ביותר)';
COMMENT ON COLUMN authority_year."periphery_edition" IS 'peripherality edition | מהדורת מדד הפריפריאליות';
COMMENT ON COLUMN authority_year."eshkol" IS 'Eshkol cluster or empty | אשכול: גליל מזרחי / גליל מערבי / ריק';

CREATE OR REPLACE VIEW observations AS SELECT * FROM read_parquet('data/release/parquet/observations.parquet');
COMMENT ON VIEW observations IS 'The values: one row per authority, indicator and data year, including CBS special symbols, with row-level quality flags. | הערכים. שורה לכל רשות, מדד ושנת נתון, כולל ערכים שהלמ"ס סימנה בסמל מיוחד, עם דגלי איכות ברמת הערך. | grain: authority × indicator × year';
COMMENT ON COLUMN observations."muni_code" IS 'authority code | סמל הרשות';
COMMENT ON COLUMN observations."indicator_id" IS 'indicator id | מזהה מדד';
COMMENT ON COLUMN observations."year" IS 'data year (not the file year); see indicators.period_kind | שנת הנתון (לא שנת הקובץ). ראו indicators.period_kind';
COMMENT ON COLUMN observations."value" IS 'numeric value after unit decisions; nil = 0 for counts; empty when no number | הערך המספרי אחרי המרת יחידות. "אין מקרים" = 0 במדדי כמות; ריק כשאין מספר';
COMMENT ON COLUMN observations."value_text" IS 'text value, or the original text when the number is malformed or a band | ערך טקסט (למדדי טקסט), או הטקסט המקורי כשהמספר פגום/טווח';
COMMENT ON COLUMN observations."flag" IS 'empty | estimate | nil | not_available | footnote | range | malformed_number | ריק = ערך רגיל · estimate = אומדן (בסוגריים במקור) · nil = "-" אין מקרים · not_available = ".." לא ידוע/לא לפרסום · footnote = עם הערת שוליים · range = טווח במקום מספר · malformed_number = מספר פגום במקור';
COMMENT ON COLUMN observations."value_published" IS 'number as published, before unit decisions | המספר כפי שפורסם, לפני המרת יחידות';
COMMENT ON COLUMN observations."unit_factor" IS 'multiplier applied (1 = none) | המקדם שהוחל (1 = ללא המרה)';
COMMENT ON COLUMN observations."data_period" IS 'period as written in the header | התקופה כפי שנכתבה בכותרת (למשל תשפ"ד 2023/24, 2020-2024)';
COMMENT ON COLUMN observations."source_file_year" IS 'file the value comes from (newest file with a value) | שנת הקובץ שממנו נלקח הערך (הקובץ החדש ביותר שיש בו ערך)';
COMMENT ON COLUMN observations."is_derived" IS 'derived value (per 1,000 residents), not published | ערך נגזר (ל-1,000 תושבים), לא פורסם ישירות';
COMMENT ON COLUMN observations."mapping_confidence" IS 'confidence that the source column belongs to this series: high | medium | low | ביטחון בשיוך עמודת המקור לסדרה: high = כותרת זהה, או התאמה שהנתונים מאששים (מתאם ≥0.9 עם השנה הסמוכה) · medium = אין נתונים לאישור / מתאם 0.5–0.9 · low = הנתונים לא ממשיכים (מתאם <0.5)';
COMMENT ON COLUMN observations."consistency_issue" IS 'value violates an internal CBS identity | הערך סותר זהות פנימית בנתוני הלמ"ס';
COMMENT ON COLUMN observations."mixed_scale" IS 'value looks like a fraction in a percentage column | הערך נראה כשבר בעמודת אחוזים (בעיה במקור)';
COMMENT ON COLUMN observations."revised" IS 'another file reported a different value (see observation_revisions) | קובץ אחר דיווח ערך שונה לאותה רשות ושנה (ראו observation_revisions)';

CREATE OR REPLACE VIEW observation_revisions AS SELECT * FROM read_parquet('data/release/parquet/observation_revisions.parquet');
COMMENT ON VIEW observation_revisions IS 'Values earlier files reported for the same authority and year that differ from the chosen value. | ערכים שקבצים קודמים דיווחו לאותה רשות ושנה ושונים מהערך הנבחר. | grain: authority × indicator × year × source file';
COMMENT ON COLUMN observation_revisions."muni_code" IS 'authority code | סמל הרשות';
COMMENT ON COLUMN observation_revisions."indicator_id" IS 'indicator id | מזהה מדד';
COMMENT ON COLUMN observation_revisions."year" IS 'data year | שנת נתון';
COMMENT ON COLUMN observation_revisions."source_file_year" IS 'file reporting this version | הקובץ שדיווח את הגרסה הזו';
COMMENT ON COLUMN observation_revisions."value" IS 'value in this version | הערך בגרסה הזו (אחרי המרת יחידות)';
COMMENT ON COLUMN observation_revisions."chosen_value" IS 'value chosen in observations | הערך שנבחר ב-observations';
COMMENT ON COLUMN observation_revisions."chosen_file_year" IS 'file of the chosen value | הקובץ של הערך שנבחר';

CREATE OR REPLACE VIEW cbs_totals AS SELECT * FROM read_parquet('data/release/parquet/cbs_totals.parquet');
COMMENT ON VIEW cbs_totals IS 'Official CBS totals: national and by municipal status. | סיכומים רשמיים של הלמ"ס: ארצי ולפי מעמד. כולל עמודה מקורית כשלא הותאמה למדד. | grain: indicator × year × group × source';
COMMENT ON COLUMN cbs_totals."row_id" IS 'row id | מזהה שורה';
COMMENT ON COLUMN cbs_totals."indicator_id" IS 'indicator id (empty if the summary label was not matched) | מזהה מדד (ריק אם הכותרת בגיליון הסיכום לא הותאמה)';
COMMENT ON COLUMN cbs_totals."year" IS 'data year | שנת נתון';
COMMENT ON COLUMN cbs_totals."group" IS 'national / municipality / local_council / regional_council | national / municipality / local_council / regional_council';
COMMENT ON COLUMN cbs_totals."value" IS 'value after unit decisions | הערך אחרי המרת יחידות';
COMMENT ON COLUMN cbs_totals."value_published" IS 'value as published | הערך כפי שפורסם';
COMMENT ON COLUMN cbs_totals."label" IS 'label in the summary sheet | הכותרת בגיליון הסיכום';
COMMENT ON COLUMN cbs_totals."source" IS 'summary_sheet or in_sheet_row | summary_sheet (2011–2021) או in_sheet_row (2022 ואילך)';
COMMENT ON COLUMN cbs_totals."source_file_year" IS 'file year | שנת הקובץ';

CREATE OR REPLACE VIEW benchmarks AS SELECT * FROM read_parquet('data/release/parquet/benchmarks.parquet');
COMMENT ON VIEW benchmarks IS 'Statistics over authorities per peer group. Unweighted unless stated. | סטטיסטיקות של כל הרשויות לפי קבוצות השוואה. ממוצעים ללא שקלול, אלא אם צוין. | grain: indicator × year × group';
COMMENT ON COLUMN benchmarks."indicator_id" IS 'indicator id | מזהה מדד';
COMMENT ON COLUMN benchmarks."year" IS 'data year | שנת נתון';
COMMENT ON COLUMN benchmarks."group_type" IS 'peer group family | national · status · ses (אשכול לשנה) · ses_latest (מהדורה אחרונה) · ses_status · eshkol';
COMMENT ON COLUMN benchmarks."group" IS 'group value | ערך הקבוצה (למשל 5, עירייה, "5 | עירייה")';
COMMENT ON COLUMN benchmarks."n" IS 'authorities with a value | מספר רשויות עם ערך';
COMMENT ON COLUMN benchmarks."mean" IS 'mean | ממוצע';
COMMENT ON COLUMN benchmarks."median" IS 'median | חציון';
COMMENT ON COLUMN benchmarks."std" IS 'standard deviation | סטיית תקן';
COMMENT ON COLUMN benchmarks."min" IS 'min | מינימום';
COMMENT ON COLUMN benchmarks."max" IS 'max | מקסימום';
COMMENT ON COLUMN benchmarks."p25" IS '25th percentile | רבעון תחתון';
COMMENT ON COLUMN benchmarks."p75" IS '75th percentile | רבעון עליון';
COMMENT ON COLUMN benchmarks."pop_weighted_mean" IS 'population-weighted mean | ממוצע משוקלל באוכלוסייה';

CREATE OR REPLACE VIEW peer_comparison AS SELECT * FROM read_parquet('data/release/parquet/peer_comparison.parquet');
COMMENT ON VIEW peer_comparison IS 'Eshkol authorities against peer groups: gaps, percentiles, z-score. | רשויות האשכול מול קבוצות ההשוואה: פערים, אחוזונים וציון z. | grain: Eshkol authority × indicator × year';
COMMENT ON COLUMN peer_comparison."muni_code" IS 'authority code | סמל הרשות';
COMMENT ON COLUMN peer_comparison."indicator_id" IS 'indicator id | מזהה מדד';
COMMENT ON COLUMN peer_comparison."year" IS 'data year | שנת נתון';
COMMENT ON COLUMN peer_comparison."value" IS 'value | הערך';
COMMENT ON COLUMN peer_comparison."ses_cluster" IS 'SES cluster for the year | אשכול חברתי-כלכלי לשנה';
COMMENT ON COLUMN peer_comparison."national_median" IS 'national median | חציון ארצי';
COMMENT ON COLUMN peer_comparison."national_n" IS 'authorities nationally | מספר רשויות בארצי';
COMMENT ON COLUMN peer_comparison."cbs_national" IS 'official national figure (2022+) | הנתון הארצי הרשמי (2022 ואילך)';
COMMENT ON COLUMN peer_comparison."pct_rank_national" IS 'national percentile 0-100 | אחוזון ארצי 0–100';
COMMENT ON COLUMN peer_comparison."gap_national_median" IS 'gap from the national median | פער מהחציון הארצי';
COMMENT ON COLUMN peer_comparison."ses_median" IS 'median of the SES cluster | חציון האשכול החברתי-כלכלי';
COMMENT ON COLUMN peer_comparison."ses_n" IS 'authorities in the SES cluster | מספר רשויות באשכול';
COMMENT ON COLUMN peer_comparison."pct_rank_ses" IS 'percentile within the SES cluster | אחוזון בתוך האשכול';
COMMENT ON COLUMN peer_comparison."z_ses" IS 'z-score within the SES cluster | ציון z בתוך האשכול';
COMMENT ON COLUMN peer_comparison."gap_ses_median" IS 'gap from the SES-cluster median | פער מחציון האשכול';
COMMENT ON COLUMN peer_comparison."ses_latest_median" IS 'median of the latest-edition SES cluster | חציון האשכול במהדורה האחרונה';
COMMENT ON COLUMN peer_comparison."status_median" IS 'median of authorities with the same status | חציון רשויות באותו מעמד';
COMMENT ON COLUMN peer_comparison."eshkol_median" IS 'median of the Eshkol cluster | חציון רשויות האשכול הגלילי';
